#!/usr/bin/env bun

type Status = "open" | "done";

interface Task {
  id: number;
  title: string;
  tags: string[];
  status: Status;
  createdAt: string;
  due?: string;
  completedAt?: string;
}

interface Database {
  nextId: number;
  tasks: Task[];
}

const databasePath = process.env.TASKBOARD_FILE || ".taskboard.json";

function fail(message: string): never {
  console.error(message);
  process.exit(1);
}

function isDate(value: string): boolean {
  if (!/^\d{4}-\d{2}-\d{2}$/.test(value)) return false;
  const [year, month, day] = value.split("-").map(Number);
  const date = new Date(year, month - 1, day);
  return date.getFullYear() === year && date.getMonth() === month - 1 && date.getDate() === day;
}

function todayLocal(): string {
  const date = new Date();
  const offset = date.getTimezoneOffset() * 60_000;
  return new Date(date.getTime() - offset).toISOString().slice(0, 10);
}

function parseId(value: string | undefined): number {
  if (!value || !/^\d+$/.test(value) || Number(value) < 1 || !Number.isSafeInteger(Number(value))) {
    fail("ID must be a positive integer");
  }
  return Number(value);
}

function validateDatabase(value: unknown): Database {
  if (!value || typeof value !== "object" || Array.isArray(value)) fail("Malformed taskboard database");
  const db = value as Partial<Database>;
  if (!Number.isSafeInteger(db.nextId) || (db.nextId as number) < 1 || !Array.isArray(db.tasks)) {
    fail("Malformed taskboard database");
  }
  const ids = new Set<number>();
  for (const task of db.tasks) {
    if (!task || typeof task !== "object" || !Number.isSafeInteger(task.id) || task.id < 1 ||
      typeof task.title !== "string" || !task.title.trim() || !Array.isArray(task.tags) ||
      !task.tags.every((tag) => typeof tag === "string") ||
      (task.status !== "open" && task.status !== "done") || typeof task.createdAt !== "string" ||
      (task.due !== undefined && (typeof task.due !== "string" || !isDate(task.due))) ||
      (task.completedAt !== undefined && typeof task.completedAt !== "string") || ids.has(task.id)) {
      fail("Malformed taskboard database");
    }
    ids.add(task.id);
  }
  return db as Database;
}

async function load(): Promise<Database> {
  const file = Bun.file(databasePath);
  if (!(await file.exists())) return { nextId: 1, tasks: [] };
  try {
    return validateDatabase(JSON.parse(await file.text()));
  } catch (error) {
    if (error instanceof SyntaxError) fail("Malformed taskboard database");
    throw error;
  }
}

async function save(db: Database): Promise<void> {
  const path = `${databasePath}.tmp-${process.pid}-${Date.now()}`;
  try {
    await Bun.write(path, `${JSON.stringify(db, null, 2)}\n`);
    await Bun.write(path, await Bun.file(path).arrayBuffer());
    await (await import("node:fs/promises")).rename(path, databasePath);
  } catch (error) {
    try { await (await import("node:fs/promises")).unlink(path); } catch { /* no temporary file */ }
    throw error;
  }
}

function optionValues(args: string[], allowed: Set<string>): Map<string, string> {
  const options = new Map<string, string>();
  for (let index = 0; index < args.length; index += 2) {
    const flag = args[index];
    const value = args[index + 1];
    if (!allowed.has(flag) || value === undefined || options.has(flag)) fail(`Invalid option: ${flag}`);
    options.set(flag, value);
  }
  return options;
}

async function main(): Promise<void> {
  const [command, ...args] = process.argv.slice(2);
  if (!command) fail("Missing command");
  const db = await load();

  if (command === "add") {
    const options = optionValues(args, new Set(["--title", "--tags", "--due"]));
    const title = options.get("--title")?.trim();
    if (!title) fail("Title is required");
    const due = options.get("--due");
    if (due !== undefined && !isDate(due)) fail("Due date must be a valid YYYY-MM-DD date");
    const tags = [...new Set((options.get("--tags") || "").split(",").map((tag) => tag.trim().toLowerCase()).filter(Boolean))];
    const task: Task = { id: db.nextId++, title, tags, status: "open", createdAt: new Date().toISOString(), ...(due ? { due } : {}) };
    db.tasks.push(task);
    await save(db);
    console.log(JSON.stringify(task));
    return;
  }

  if (command === "list") {
    const options = optionValues(args, new Set(["--status", "--tag", "--overdue"]));
    const status = options.get("--status");
    const tag = options.get("--tag")?.trim().toLowerCase();
    const overdue = options.get("--overdue");
    if (status !== undefined && status !== "open" && status !== "done") fail("Status must be open or done");
    if (overdue !== undefined && !isDate(overdue)) fail("Overdue date must be a valid YYYY-MM-DD date");
    const tasks = db.tasks.filter((task) =>
      (!status || task.status === status) && (!tag || task.tags.includes(tag)) &&
      (!overdue || (task.status === "open" && task.due !== undefined && task.due < overdue)),
    ).sort((a, b) => a.id - b.id);
    console.log(JSON.stringify(tasks));
    return;
  }

  if (command === "done" || command === "delete") {
    if (args.length !== 1) fail(`${command} requires one ID`);
    const id = parseId(args[0]);
    const index = db.tasks.findIndex((task) => task.id === id);
    if (index === -1) fail(`Task ${id} not found`);
    if (command === "delete") {
      const [task] = db.tasks.splice(index, 1);
      await save(db);
      console.log(JSON.stringify(task));
      return;
    }
    const task = db.tasks[index];
    if (task.status === "open") {
      task.status = "done";
      task.completedAt = new Date().toISOString();
      await save(db);
    }
    console.log(JSON.stringify(task));
    return;
  }

  if (command === "stats") {
    if (args.length) fail("stats accepts no options");
    const today = todayLocal();
    const open = db.tasks.filter((task) => task.status === "open");
    console.log(JSON.stringify({ total: db.tasks.length, open: open.length, done: db.tasks.length - open.length, overdue: open.filter((task) => task.due && task.due < today).length }));
    return;
  }

  fail(`Unknown command: ${command}`);
}

main().catch((error) => fail(error instanceof Error ? error.message : String(error)));
